INSERT INTO `tipo_evento` VALUES (5918165,'Residencial Aurora Pinheiros','residencial-aurora-pinheiros','Lançamento exclusivo com design biofílico, lazer no rooftop e localização privilegiada próxima ao metrô.',60,60,0,20),(5918172,'Skyline Moema','skyline-moema','Apartamentos compactos de luxo, ideais para investimento ou moradia moderna no coração de Moema.',60,60,0,21),(5918174,'Itaim Premium Living','itaim-premium-living','O auge da sofisticação com pé direito duplo e vista definitiva para o skyline da cidade.',60,60,0,22),(5918183,'Brooklin Horizon','brooklin-horizon','Conceito aberto e moderno, focado em mobilidade urbana e coworking integrado ao condomínio.',60,60,0,23),(5918185,'Vila Mariana Green House','vila-mariana-green-house','Lançamento sustentável com horta comunitária e reaproveitamento de água, ao lado do Parque Ibirapuera.',60,60,0,24),(5918186,'Urban Perdizes','urban-perdizes','Obra em estágio avançado. Apartamento com excelente distribuição interna em bairro tradicional.',60,60,0,25),(5918187,'Metrópole Tatuapé','metrpole-tatuap','Em obras aceleradas. Complexo moderno com integração total ao shopping e metrô.',60,60,0,26),(5918191,'Belém Garden Residence','belm-garden-residence','Construção iniciada. Apartamentos com varanda gourmet e lazer completo para crianças.',60,60,0,27),(5918200,'Morumbi View Tower','morumbi-view-tower','Em obras. Vista panorâmica para a ponte estaiada com acabamento em mármore importado.',60,60,0,28),(5918201,'Santana Sky Home','santana-sky-home','Fase de acabamento. Estrutura de lazer completa no último andar com piscina infinita.',60,60,0,29),(5918204,'Classic Higienópolis','classic-higienpolis','Totalmente reformado em estilo retro-contemporâneo. Pronto para morar em rua arborizada.',60,60,0,30),(5918205,'Modern Jardins Loft','modern-jardins-loft','Lindo loft mobiliado com móveis planejados de alto padrão, ar condicionado e automação.',60,60,0,31),(5918214,'Life Butantã','life-butant','Excelente oportunidade para jovens profissionais. Próximo à USP com lazer completo.',60,60,0,32),(5918215,'Sacomã Residence Club','sacom-residence-club','Apartamento ensolarado, andar alto com vista para o parque e 2 vagas fixas de garagem.',60,60,0,33),(5918219,'Conquista Lapa','conquista-lapa','Imóvel pronto, recém pintado e com armários embutidos em todos os cômodos.',60,60,0,34);

